/* ==========================================================================
 * Op parameter inventory -- the fix for the Inspector's overfit schema
 * --------------------------------------------------------------------------
 * THE PROBLEM (measured, docs/NATIVE_PORT.md 5.5)
 *   game/data/effect-schema.json is generated by OBSERVING the card pool. It
 *   therefore only describes parameter spellings that some real card already
 *   used. Measured gap against the code:
 *
 *     ops whose handler reads parameters : 111
 *       schema agrees                    :  38
 *       schema is missing fields         :  73     <-- 66%
 *       total parameter references in code: 374
 *
 *   Worst cases are ops no card has exercised yet: conditionalRandomSplit has
 *   26 parameter reads and ZERO schema entries; asVar 10; handToField 6.
 *   That is why the Inspector needs hand-written UI per effect (4910 lines /
 *   40 blocks): the generated schema cannot drive a generic editor for the
 *   majority of ops, so the generic fallback degrades to bare JSON.
 *
 * THE FIX THIS TOOL PROVIDES
 *   The authoritative spelling list is not in the data, it is in effects.js:
 *   an op's parameters are exactly the `a.<field>` reads inside its handler.
 *   This extracts them statically, with no engine execution and no pool
 *   dependence, so it covers ops that no card has ever used.
 *
 *   Output is a PROPOSAL, not a patch: it is meant to be merged into whatever
 *   generates effect-schema.json so the schema stops being pool-dependent.
 *   Labels come from a separate table (126 ops, currently all null).
 *
 * SCOPE / LIMITS -- do not oversell this
 *   * It finds SPELLINGS, not types. `a.amount` could be a number, a stat
 *     reference or a count expression; only the handler's use tells you, and
 *     inference from source is future work. Types stay as observed-or-null.
 *   * A handler that reads `a` generically (spread, dynamic key) yields nothing;
 *     those ops are reported separately so the gap is visible rather than
 *     silently empty.
 *   * Aliases (OPS.x = OPS.y) inherit the target's list.
 *
 * Usage:
 *   node tools/inspector/op-param-inventory.js                  # report
 *   node tools/inspector/op-param-inventory.js --out proposal.json
 *   node tools/inspector/op-param-inventory.js --compare
 * ========================================================================== */
'use strict';
const fs = require('fs');
const path = require('path');

const REPO = process.env.KG_REPO || path.resolve(__dirname,'../../resources/app');
const GAME = path.join(REPO, 'game');

function arg(name, dflt) {
  const i = process.argv.indexOf(name);
  return i >= 0 && process.argv[i + 1] !== undefined ? process.argv[i + 1] : dflt;
}

/* ------------------------------------------------------- handler boundaries */
function parseHandlers(src) {
  const lines = src.split('\n');
  const marks = [];
  lines.forEach((l, i) => {
    const m = l.match(/^\s*OPS\.(\w+)\s*=/);
    if (m) marks.push({ name: m[1], at: i, def: l.trim() });
  });
  return marks.map((m, k) => ({
    name: m.name,
    def: m.def,
    from: m.at,
    to: k + 1 < marks.length ? marks[k + 1].at : lines.length,
    body: lines.slice(m.at, k + 1 < marks.length ? marks[k + 1].at : lines.length).join('\n'),
  }));
}

/**
 * Parameter spellings an op reads off the action object.
 *
 * Only direct member reads count: a.amount, a["amount"]. The bracket form is
 * included because effects.js uses it for a few computed names; the literal is
 * taken only when it is a plain string, so a computed key yields nothing rather
 * than a wrong guess.
 */
function paramSpellings(body) {
  const out = new Set();
  for (const m of body.matchAll(/\ba\.(\w+)/g)) out.add(m[1]);
  for (const m of body.matchAll(/\ba\[\s*['"]([A-Za-z_]\w*)['"]\s*\]/g)) out.add(m[1]);
  return [...out].sort();
}

/** Does the handler consume the action object opaquely (spread / dynamic key)? */
function opaqueUse(body) {
  return /\.\.\.\s*a\b/.test(body)
    || /\ba\[\s*[^'"]/.test(body)
    || /Object\.(keys|entries|assign)\(\s*a\b/.test(body);
}

/* ------------------------------------------------------------------- report */
function main() {
  const src = fs.readFileSync(path.join(GAME, 'js', 'effects.js'), 'utf8');
  const handlers = parseHandlers(src);

  const aliases = {};
  const direct = {};
  const opaque = [];

  for (const h of handlers) {
    const m = h.def.match(/^OPS\.(\w+)\s*=\s*OPS\.(\w+)\s*;/);
    if (m) { aliases[h.name] = m[2]; continue; }
    const params = paramSpellings(h.body);
    direct[h.name] = params;
    if (!params.length && opaqueUse(h.body)) opaque.push(h.name);
  }

  // Resolve aliases onto their target's spelling list.
  const resolved = {};
  for (const [name, params] of Object.entries(direct)) resolved[name] = params;
  for (const [alias, target] of Object.entries(aliases)) {
    resolved[alias] = resolved[target] || [];
  }

  const schemaPath = path.join(GAME, 'data', 'effect-schema.json');
  const hasSchema = fs.existsSync(schemaPath);
  const schema = hasSchema
    ? JSON.parse(fs.readFileSync(schemaPath, 'utf8').replace(/^\uFEFF/, ''))
    : { ops: {} };

  const rows = Object.entries(resolved)
    .map(([name, real]) => {
      const sp = Object.keys((schema.ops && schema.ops[name] && schema.ops[name].params) || {});
      const missing = real.filter(p => !sp.includes(p));
      const extra = sp.filter(p => !real.includes(p));
      return { name, real, schemaParams: sp, missing, extra, aliasOf: aliases[name] || null };
    })
    .sort((a, b) => b.missing.length - a.missing.length || a.name.localeCompare(b.name));

  const withParams = rows.filter(r => r.real.length);
  const agree = withParams.filter(r => !r.missing.length).length;
  const gap = withParams.filter(r => r.missing.length).length;
  const totalReal = withParams.reduce((s, r) => s + r.real.length, 0);
  const totalMissing = withParams.reduce((s, r) => s + r.missing.length, 0);

  console.log('=== op parameter inventory (from effects.js source) ===');
  console.log('  handlers parsed            : ' + handlers.length);
  console.log('  aliases resolved           : ' + Object.keys(aliases).length);
  console.log('  ops reading parameters     : ' + withParams.length);
  console.log('  ops consuming `a` opaquely : ' + opaque.length +
    (opaque.length ? '  (' + opaque.join(', ') + ')' : ''));
  console.log('  parameter spellings in code: ' + totalReal);
  console.log('');
  console.log('  against the observed schema :');
  console.log('    schema agrees            : ' + agree);
  console.log('    schema missing fields    : ' + gap + ' ops, ' + totalMissing + ' fields');
  console.log('    schema-only (unused)     : ' +
    withParams.filter(r => r.extra.length).length + ' ops');

  console.log('');
  console.log('  worst gaps (schema=0 means nothing is described):');
  rows.filter(r => r.missing.length).slice(0, 15).forEach(r => {
    console.log('    ' + r.name.padEnd(24) +
      'schema=' + String(r.schemaParams.length).padStart(2) +
      '  code=' + String(r.real.length).padStart(2) +
      '  missing=' + String(r.missing.length).padStart(2) +
      '  ' + r.missing.slice(0, 6).join(',') + (r.missing.length > 6 ? ',...' : ''));
  });

  const out = arg('--out', null);
  if (out) {
    // The shape mirrors effect-schema.json's ops entries so it can be merged
    // rather than converted: only the params map is authored here.
    const proposal = {
      _note: 'Generated by tools/inspector/op-param-inventory.js from effects.js. '
        + 'Parameter SPELLINGS only -- types remain whatever the observed schema said. '
        + 'Merge into the effect-schema generator so the schema stops depending on card-pool usage.',
      source: { registry: 'js/effects.js OPS handlers', handlers: handlers.length },
      counts: {
        opsReadingParams: withParams.length,
        spellingsInCode: totalReal,
        missingFromObservedSchema: totalMissing,
      },
      ops: {},
    };
    for (const r of rows) {
      if (!r.real.length) continue;
      proposal.ops[r.name] = {
        params: Object.fromEntries(r.real.map(p => [p, { spellingOnly: true }])),
        missingFromObservedSchema: r.missing,
        aliasOf: r.aliasOf,
      };
    }
    fs.mkdirSync(path.dirname(out), { recursive: true });
    fs.writeFileSync(out, JSON.stringify(proposal, null, 1), 'utf8');
    console.log('\n  proposal written: ' + out);
  }

  if (process.argv.includes('--compare')) {
    console.log('\n=== full table (missing fields per op) ===');
    rows.filter(r => r.missing.length).forEach(r => {
      console.log('  ' + r.name + ':' + r.missing.join(','));
    });
  }

  process.exitCode = gap ? 1 : 0;
}

main();
